package app.veyra;
import android.app.*;import android.graphics.Color;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.function.IntConsumer;
final class ActionSheet {
 static Dialog show(Activity a,String title,String[] labels,IntConsumer action){Dialog d=new Dialog(a);LinearLayout panel=Ui.column(a);GradientDrawable bg=new GradientDrawable();bg.setColor(Ui.SURFACE);bg.setCornerRadius(Ui.dp(a,24));panel.setBackground(bg);panel.setPadding(Ui.dp(a,20),Ui.dp(a,12),Ui.dp(a,20),Ui.dp(a,24));LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);TextView name=Ui.text(a,title,22,Ui.INK);name.setTypeface(null,android.graphics.Typeface.BOLD);heading.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button close=Ui.quiet(a,"×");close.setContentDescription("Close panel");close.setOnClickListener(v->d.dismiss());heading.addView(close,new LinearLayout.LayoutParams(Ui.dp(a,48),Ui.dp(a,48)));panel.addView(heading);ScrollView scroll=new ScrollView(a);LinearLayout rows=Ui.column(a);rows.setBackgroundColor(Color.TRANSPARENT);for(int i=0;i<labels.length;i++){final int index=i;Button row=Ui.quiet(a,labels[i]);row.setSingleLine(false);row.setGravity(Gravity.CENTER_VERTICAL|Gravity.START);row.setTextSize(15);row.setPadding(Ui.dp(a,12),Ui.dp(a,12),Ui.dp(a,12),Ui.dp(a,12));row.setOnClickListener(v->{d.dismiss();action.accept(index);});rows.addView(row,new LinearLayout.LayoutParams(-1,-2));}scroll.addView(rows);panel.addView(scroll);d.setContentView(panel);Window w=d.getWindow();if(w!=null){w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams lp=w.getAttributes();lp.gravity=Gravity.BOTTOM;lp.dimAmount=.45f;w.setAttributes(lp);}d.show();if(w!=null){int width=Math.min(a.getResources().getDisplayMetrics().widthPixels-Ui.dp(a,16),Ui.dp(a,640));panel.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));w.setLayout(width,Math.min(panel.getMeasuredHeight(),(int)(a.getResources().getDisplayMetrics().heightPixels*.82)));}return d;}
}
